function create() {
    // Create the paddle
    this.paddle = this.physics.add.sprite(400, 550, 'paddle');
    this.paddle.setImmovable(true);
    this.paddle.setScale(2);
    this.paddle.body.collideWorldBounds = true;
}

function preload() {
    // Generate paddle graphic
    const paddleGraphics = this.make.graphics({ x: 0, y: 0 });
    paddleGraphics.fillStyle(0xFFFFFF);
    paddleGraphics.fillRect(0, 0, 100, 20);
    paddleGraphics.generateTexture('paddle', 100, 20);
    paddleGraphics.destroy();
}

function create() {
    // Create game objects here
    this.orc = this.physics.add.sprite(400, 300, 'orc', 0);
    this.cursors = this.input.keyboard.createCursorKeys();
}

function update() {
    // Update game logic here
    if (this.cursors.left.isDown) {
        this.orc.setVelocityX(-160);
    } else if (this.cursors.right.isDown) {
        this.orc.setVelocityX(160);
    } else {
        this.orc.setVelocityX(0);
    }

    if (this.cursors.up.isDown) {
        this.orc.setVelocityY(-160);
    } else if (this.cursors.down.isDown) {
        this.orc.setVelocityY(160);
    } else {
        this.orc.setVelocityY(0);
    }
}

