    this.anims.create({
        key: 'left',
        frames: this.anims.generateFrameNumbers('orc', { start: 0, end: 5 }),
        frameRate: 10,
        repeat: -1
    });

    this.anims.create({
        key: 'turn',
        frames: [{ key: 'orc', frame: 6 }],
        frameRate: 20
    });

    this.anims.create({
        key: 'right',
        frames: this.anims.generateFrameNumbers('orc', { start: 7, end: 12 }),
        frameRate: 10,
        repeat: -1
    });

    // Input System: Handle keyboard input for movement
    this.cursors = this.input.keyboard.createCursorKeys();

    // Create a group for coins
    this.coins = this.physics.add.group({
        key: 'coin',
        repeat: 10,
        setXY: { x: 12, y: 0, stepX: 70 }
    });

    // Set coin physics properties
    this.coins.children.iterate(function (child) {
        child.setBounceY(Phaser.Math.FloatBetween(0.4, 0.8));
    });

    // Physics System: Handle collisions and movement physics
    this.physics.world.setBoundsCollision(true, true, true, false);
    this.physics.add.collider(this.player, this.coins, collectCoin, null, this);
}

function collectCoin(player, coin) {
    coin.disableBody(true, true);
    // Inventory System: Track collected coins
    this.score += 10;
    this.scoreText.setText('Score: ' + this.score);
}

