function clamp(value, min, max) {
  if (typeof value !== 'number' || isNaN(value)) {
    throw new Error('Value must be a number');
  }
  if (typeof min !== 'number' || isNaN(min)) {
    throw new Error('Min must be a number');
  }
  if (typeof max !== 'number' || isNaN(max)) {
