function chunk(arr, n) {
    if (!Array.isArray(arr)) {
        throw new TypeError("chunk expects an array as first argument");
    }
    if (n < 1) {
        throw new Error("n must be at least 1");
    }
    const result = [];
    for (let i = 0; i < arr.length; i += n) {
        result.push(arr.slice(i, i + n));
    }
