}

// Zip two arrays together
function zip(a, b) {
    if (!Array.isArray(a)) {
        throw new TypeError("zip expects first argument to be an array");
    }
    if (!Array.isArray(b)) {
        throw new TypeError("zip expects second argument to be an array");
    }
    const result = [];
    const len = Math.min(a.length, b.length);
    for (let i = 0; i < len; i++) {
        result.push([a[i], b[i]]);
    }
    return result;
}

