def parse_args(argv):
    """
    Parse command line arguments and return them as a dictionary.

    Args:
        argv: List of command line arguments (excluding script name)

    Returns:
        dict: Dictionary containing parsed arguments
    """
    result = {}

    # Simple argument parsing - handle flags and key-value pairs
    i = 0
    while i < len(argv):
        arg = argv[i]

        # Handle flags (starting with - or --)
        if arg.startswith('--'):
            flag = arg[2:]  # Remove '--'
            if i + 1 < len(argv) and not argv[i + 1].startswith('-'):
                # Flag with value
                result[flag] = argv[i + 1]
                i += 2
            else:
                # Flag without value (boolean flag)
                result[flag] = True
                i += 1
        elif arg.startswith('-'):
            flag = arg[1:]  # Remove '-'
            if i + 1 < len(argv) and not argv[i + 1].startswith('-'):
                # Flag with value
                result[flag] = argv[i + 1]
                i += 2
            else:
                # Flag without value (boolean flag)
                result[flag] = True
                i += 1
        else:
            # Positional argument
            if 'positional' not in result:
                result['positional'] = []
            result['positional'].append(arg)
            i += 1

    return result

