    for (const item of arr) {
        const key = keyFn(item);
        if (!seen.has(key)) {
            seen.add(key);
            result.push(item);
        }
    }

    return result;
}

module.exports = { dedupeBy };

const { dedupeBy } = require('./r10_dedupe');

// Test 1: Basic deduplication by string key
const test1 = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
    { id: 3, name: 'Alice' },
    { id: 4, name: 'Charlie' }
];

const result1 = dedupeBy(test1, item => item.name);
console.assert(JSON.stringify(result1) === JSON.stringify([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
    { id: 4, name: 'Charlie' }
]), 'Test 1 failed: Basic deduplication by string key');

// Test 2: Deduplication by number key
const test2 = [
    { id: 1, value: 10 },
    { id: 2, value: 20 },
    { id: 3, value: 10 },
    { id: 4, value: 30 }
];

const result2 = dedupeBy(test2, item => item.value);
console.assert(JSON.stringify(result2) === JSON.stringify([
    { id: 1, value: 10 },
    { id: 2, value: 20 },
    { id: 4, value: 30 }
]), 'Test 2 failed: Deduplication by number key');

// Test 3: Empty array
const test3 = [];
const result3 = dedupeBy(test3, item => item.id);
console.assert(JSON.stringify(result3) === JSON.stringify([]), 'Test 3 failed: Empty array');

// Test 4: No duplicates
const test4 = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
    { id: 3, name: 'Charlie' }
];

const result4 = dedupeBy(test4, item => item.id);
console.assert(JSON.stringify(result4) === JSON.stringify(test4), 'Test 4 failed: No duplicates');

// Test 5: All duplicates
const test5 = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Alice' },
    { id: 3, name: 'Alice' }
];

const result5 = dedupeBy(test5, item => item.name);
console.assert(JSON.stringify(result5) === JSON.stringify([
    { id: 1, name: 'Alice' }
]), 'Test 5 failed: All duplicates');

// Test 6: Complex objects
const test6 = [
    { id: 1, data: { x: 1, y: 2 } },
    { id: 2, data: { x: 3, y: 4 } },
    { id: 3, data: { x: 1, y: 2 } }
