        print(f"Running {test_file}...")
        try:
            # For JavaScript files, we can use node
            if test_file.endswith('.js'):
                result = subprocess.run(['node', test_file], capture_output=True, text=True, timeout=30)
            # For markdown files, we could potentially run them as scripts if they contain executable code
            # For now, we'll just report they exist
            else:
