/**
 * Converts a string to a URL slug format
 * @param {string} s - The input string
 * @returns {string} - The slugified string
 * @throws {Error} - If input is not a string
 */
function slug(s) {
  if (typeof s !== 'string') {
    throw new Error('Input must be a string');
  }
  return s.toLowerCase()
    .replace(/\s+/g, '-')
    .replace(/[^a-z0-9-]/g, '')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');
}

/**
