 * @param {string} s - The input string
 * @returns {string} - The title
 * @throws {Error} - If input is not a string
 */
function title(s) {
  if (typeof s !== 'string') {
    throw new Error('Input must be a string');
  }
  return s.trim().split(/\s+/)[0];
}

