// q3_list.js - Array manipulation functions

// Export the functions
module.exports = {
  uniq: function(arr) {
    return [...new Set(arr)];
  },
  flatten: function(arr) {
    return arr.reduce((acc, val) => acc.concat(val), []);
  },
  chunk: function(arr, n) {
    const result = [];
    for (let i = 0; i < arr.length; i += n) {
      result.push(arr.slice(i, i + n));
    }
    return result;
  }
};
```

