// Export slug function
function slug(s) {
    // Validate input
    if (typeof s !== 'string') {
        throw new Error('Input must be a string');
    }

    // Convert to lowercase, replace non-alphanumeric characters with hyphens, 
    // remove leading/trailing hyphens, and collapse multiple hyphens
    return s.toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '')
        .replace(/-+/g, '-');
}

// Export title function
function title(s) {
    // Validate input
    if (typeof s !== 'string') {
        throw new Error('Input must be a string');
    }

    // Split by spaces, capitalize first letter of each word, join back with spaces
    return s.split(' ')
        .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
        .join(' ');
}

module.exports = { slug, title };

// Split array into chunks of size n
function chunk(arr, n) {
    const result = [];
    for (let i = 0; i < arr.length; i += n) {
        result.push(arr.slice(i, i + n));
    }
    return result;
}

// Zip two arrays together
function zip(a, b) {
    const result = [];
    const len = Math.min(a.length, b.length);
    for (let i = 0; i < len; i++) {
        result.push([a[i], b[i]]);
    }
    return result;
}

// Generate a range of numbers
function range(n) {
    const result = [];
    for (let i = 0; i < n; i++) {
        result.push(i);
    }
    return result;
}

// Export the functions
module.exports = { uniq, flatten, chunk, zip, range };

