// clamp function - restricts a value between low and high bounds
function clamp(v, lo, hi) {
  if (typeof v !== 'number' || typeof lo !== 'number' || typeof hi !== 'number') {
    throw new Error('All arguments to clamp must be numbers');
  }
  if (lo > hi) {
    throw new Error('Lower bound cannot be greater than upper bound in clamp');
  }
  return Math.min(Math.max(v, lo), hi);
}

// randInt function - generates a random integer between low and high (inclusive)
function randInt(lo, hi) {
  if (typeof lo !== 'number' || typeof hi !== 'number') {
    throw new Error('All arguments to randInt must be numbers');
  }
  if (lo > hi) {
    throw new Error('Lower bound cannot be greater than upper bound in randInt');
  }
  return Math.floor(Math.random() * (hi - lo + 1)) + lo;
}

// lerp function - linear interpolation between two values
function lerp(a, b, t) {
  if (typeof a !== 'number' || typeof b !== 'number' || typeof t !== 'number') {
    throw new Error('All arguments to lerp must be numbers');
  }
  if (t < 0 || t > 1) {
    throw new Error('Interpolation parameter t must be between 0 and 1');
  }
  return a + (b - a) * t;
}

// Self-checks to verify the functions work correctly
try {
  // Test clamp function
  if (clamp(5, 1, 10) !== 5) throw new Error('clamp(5, 1, 10) should return 5');
  if (clamp(0, 1, 10) !== 1) throw new Error('clamp(0, 1, 10) should return 1');
  if (clamp(15, 1, 10) !== 10) throw new Error('clamp(15, 1, 10) should return 10');

  // Test randInt function
  const results = [];
  for (let i = 0; i < 100; i++) {
    const val = randInt(1, 6);
    if (val < 1 || val > 6) throw new Error(`randInt(1, 6) returned ${val}, should be between 1 and 6`);
    results.push(val);
  }

  // Verify we got a range of values (not all the same)
  const uniqueValues = new Set(results);
  if (uniqueValues.size < 3) throw new Error('randInt(1, 6) should produce a variety of values');

  // Test error cases for clamp
  try {
    clamp('invalid', 1, 10);
    throw new Error('clamp should throw on non-numeric input');
  } catch (e) {
    if (!e.message.includes('All arguments to clamp must be numbers')) {
      throw new Error('clamp should throw correct error for non-numeric input');
    }
  }

  try {
    clamp(5, 10, 1);
    throw new Error('clamp should throw when lower bound > upper bound');
  } catch (e) {
    if (!e.message.includes('Lower bound cannot be greater than upper bound')) {
      throw new Error('clamp should throw correct error for invalid bounds');
    }
  }

  // Test error cases for randInt
  try {
    randInt('invalid', 10);
    throw new Error('randInt should throw on non-numeric input');
  } catch (e) {
    if (!e.message.includes('All arguments to randInt must be numbers')) {
      throw new Error('randInt should throw correct error for non-numeric input');
    }
  }

  try {
    randInt(10, 1);
    throw new Error('randInt should throw when lower bound > upper bound');
  } catch (e) {
    if (!e.message.includes('Lower bound cannot be greater than upper bound')) {
      throw new Error('randInt should throw correct error for invalid bounds');
    }
  }

  console.log('All self-checks passed!');
} catch (error) {
  console.error('Self-check failed:', error.message);
  throw error;
}

// Export the functions
module.exports = { clamp, randInt, lerp };

