    """Convert seconds to human-readable format like '2m 3s'"""
    if seconds < 60:
        return f"{seconds}s"

    minutes = seconds // 60
    remaining_seconds = seconds % 60

    if remaining_seconds == 0:
        return f"{minutes}m"
    else:
        return f"{minutes}m {remaining_seconds}s"

