// clamp function - restricts a value between low and high bounds
function clamp(v, lo, hi) {
  if (typeof v !== 'number' || typeof lo !== 'number' || typeof hi !== 'number') {
    throw new Error('All arguments to clamp must be numbers');
  }
  if (lo > hi) {
    throw new Error('Lower bound cannot be greater than upper bound in clamp');
  }
  return Math.min(Math.max(v, lo), hi);
}

// randInt function - generates a random integer between low and high (inclusive)
function randInt(lo, hi) {
  if (typeof lo !== 'number' || typeof hi !== 'number') {
    throw new Error('All arguments to randInt must be numbers');
  }
  if (lo > hi) {
    throw new Error('Lower bound cannot be greater than upper bound in randInt');
  }
  return Math.floor(Math.random() * (hi - lo + 1)) + lo;
}

// lerp function - linear interpolation between two values
function lerp(a, b, t) {
  if (typeof a !== 'number' || typeof b !== 'number' || typeof t !== 'number') {
    throw new Error('All arguments to lerp must be numbers');
  }
  if (t < 0 || t > 1) {
    throw new Error('Interpolation parameter t must be between 0 and 1');
  }
  return a + (b - a) * t;
}

