function add(a, b) {
    if (a === undefined || b === undefined) {
        throw new Error("Vector addition requires two arguments");
    }
    if (typeof a !== 'object' || a === null || !('x' in a) || !('y' in a)) {
        throw new Error("First argument must be an object with x and y properties");
    }
    if (typeof b !== 'object' || b === null || !('x' in b) || !('y' in b)) {
        throw new Error("Second argument must be an object with x and y properties");
    }
    return {x: a.x + b.x, y: a.y + b.y};
}

