#!/usr/bin/env python3
import subprocess
import sys
import os

# List of test files to run
test_files = [
    'y1_dates.js',
    'y2_uuid.js', 
    'y3_color.js',
    'y4_csv.js',
    'y5_env.md',
    'y6_deps.md',
    'y7_lint.js'
]

# Run each test file
for test_file in test_files:
    if os.path.exists(test_file):
        print(f"Running {test_file}...")
        try:
            # For JavaScript files, we can use node
            if test_file.endswith('.js'):
                result = subprocess.run(['node', test_file], capture_output=True, text=True, timeout=30)
            # For markdown files, we could potentially run them as scripts if they contain executable code
            # For now, we'll just report they exist
            else:
                print(f"  {test_file} - exists (not executable)")
                continue

            if result.returncode == 0:
                print(f"  PASS {test_file} passed")
            else:
                print(f"  FAIL {test_file} failed")
                print(f"    Error: {result.stderr}")
        except subprocess.TimeoutExpired:
            print(f"  FAIL {test_file} timed out")
        except Exception as e:
            print(f"  FAIL {test_file} error: {e}")
    else:
        print(f"  {test_file} - not found")

print("Test execution completed.")

