// q3_list.js - Array manipulation functions

// Remove duplicates from an array
function uniq(arr) {
    return [...new Set(arr)];
}

// Flatten nested arrays
function flatten(arr) {
    return arr.flat();
}

// Split array into chunks of size n
function chunk(arr, n) {
    const result = [];
    for (let i = 0; i < arr.length; i += n) {
        result.push(arr.slice(i, i + n));
    }
    return result;
}

// Zip two arrays together
function zip(a, b) {
    const result = [];
    const len = Math.min(a.length, b.length);
    for (let i = 0; i < len; i++) {
        result.push([a[i], b[i]]);
    }
    return result;
}

// Generate a range of numbers
function range(n) {
    const result = [];
    for (let i = 0; i < n; i++) {
        result.push(i);
    }
    return result;
}

module.exports = { uniq, flatten, chunk, zip, range };

