/**
 * Convert a string to a URL-friendly slug (lowercase, spaces to dashes)
 * @param {string} s - Input string
 * @returns {string} - Slugified string
 */
function slug(s) {
  if (typeof s !== 'string') {
    throw new Error('Input must be a string');
  }
  return s.toLowerCase().replace(/\s+/g, '-');
}

