      throw new Error("zip: expected first argument to be an array");
    }
    if (!Array.isArray(b)) {
      throw new Error("zip: expected second argument to be an array");
    }
    var result = [];
    var len = Math.min(a.length, b.length);
    for (var i = 0; i < len; i++) {
      result.push([a[i], b[i]]);
    }
    return result;
