// Benchmark script to time summing one million numbers

function benchmarkSum() {
    const start = performance.now();

    let sum = 0;
    for (let i = 0; i < 1000000; i++) {
        sum += i;
    }

    const end = performance.now();
    return end - start;
}

// Run the benchmark three times
const results = [];
for (let i = 0; i < 3; i++) {
    const time = benchmarkSum();
    results.push(time);
    console.log(`Run ${i + 1}: ${time.toFixed(2)} milliseconds`);
}

// Calculate and display average
const average = results.reduce((a, b) => a + b, 0) / results.length;
console.log(`Average: ${average.toFixed(2)} milliseconds`);

